  opts=["نقل","تغيير الحجم","تدوير","شفافية وظل","تكرار","حذف","وضع في صفحة أخرى","تركيب فوق خلفية جديدة"],
  faq=[("هل الأداة مجانية؟","نعم، تعمل داخل متصفحك دون مفتاح؛ تنزيل النماذج يتم مرة واحدة ثم تُحفظ."),("هل تُبنى الخلفية خلف العنصر بعد نقله؟","تُملأ منطقة العنصر المنقول بترميم محلي تتفاوت جودته؛ الخلفيات البسيطة أنسب من المعقدة."),("هل يلتقط كل شيء بدقة؟","لا؛ تتفاوت الدقة مع الشعر والأجسام الشفافة والعناصر المتداخلة، وللمناطق الدقيقة ارسم مستطيلاً حولها."),("هل صوري تُرفع إلى خادم؟","التحليل يتم داخل متصفحك.")],
